-- AWS Security Specialty (SCS-C02) questions. Domains 1 Threat Detection/IR (14%),
-- 2 Logging & Monitoring (18%), 3 Infrastructure (20%), 4 IAM (16%),
-- 5 Data Protection (18%), 6 Governance (14%).
insert into public.questions (id, cert, domain, objective, qtype, difficulty, stem, choices, answer, explanation) values
-- Domain 1: Threat Detection & Incident Response
('sc-q-001','awsscs',1,'1.1','mcq',2,$q$Which service analyzes CloudTrail, VPC Flow Logs, and DNS logs to detect threats without deploying agents?$q$,$q$["Amazon Macie","Amazon GuardDuty","AWS Config","Amazon Inspector"]$q$::jsonb,'1'::jsonb,$q$GuardDuty is the agentless threat-detection service consuming CloudTrail, VPC Flow Logs, and DNS logs with ML and threat intel. Macie classifies S3 data, Config tracks configuration, Inspector scans for vulnerabilities.$q$),
('sc-q-002','awsscs',1,'1.1','mcq',2,$q$After a GuardDuty finding, which service helps you visualize and investigate the root cause across linked activity?$q$,$q$["Amazon Detective","AWS Shield","Amazon Macie","AWS Budgets"]$q$::jsonb,'0'::jsonb,$q$Amazon Detective builds linked graphs from CloudTrail, VPC Flow Logs, and GuardDuty to investigate root cause and scope. Shield is DDoS, Macie is data classification, Budgets is cost.$q$),
('sc-q-003','awsscs',1,'1.2','mcq',3,$q$You want a GuardDuty high-severity finding to automatically isolate the affected EC2 instance. Which pattern achieves this?$q$,$q$["A CloudWatch dashboard","An EventBridge rule triggering a Lambda that applies a quarantine security group","An S3 lifecycle policy","A Route 53 health check"]$q$::jsonb,'1'::jsonb,$q$EventBridge matches the GuardDuty finding and invokes a Lambda (or SSM Automation) to apply an isolating security group and preserve evidence. Dashboards, lifecycle policies, and health checks don't automate response.$q$),
('sc-q-004','awsscs',1,'1.2','ordering',3,$q$Order the initial containment steps for a compromised EC2 instance.$q$,$q$["Isolate with a restrictive security group","Snapshot the EBS volume and capture memory for evidence","Detach from the Auto Scaling group","Rotate exposed credentials"]$q$::jsonb,$q$[0,1,2,3]$q$::jsonb,$q$Isolate first to stop further damage, preserve evidence (snapshot/memory) before it's lost, detach from Auto Scaling so it isn't terminated/replaced mid-investigation, then rotate any exposed credentials to prevent reuse.$q$),
('sc-q-005','awsscs',1,'1.1','mcq',2,$q$Which service centralizes findings from GuardDuty, Inspector, and Macie and runs compliance-standard checks?$q$,$q$["AWS Security Hub","AWS CloudTrail","Amazon Detective","AWS Config"]$q$::jsonb,'0'::jsonb,$q$Security Hub aggregates findings across security services and runs automated checks against CIS, PCI DSS, and AWS FSBP. CloudTrail logs API calls, Detective investigates, Config tracks resource state.$q$),
('sc-q-006','awsscs',1,'1.2','mcq',2,$q$An IAM access key was accidentally committed to a public GitHub repo. What is the FIRST action?$q$,$q$["Create a second key","Immediately deactivate/delete the exposed key, then review CloudTrail for misuse","Email the security team and wait","Rotate it next maintenance window"]$q$::jsonb,'1'::jsonb,$q$Deactivate/delete the leaked key immediately to stop use, then investigate CloudTrail for unauthorized activity and rotate credentials. Delay or adding a key alongside leaves the exposed key active.$q$),
('sc-q-007','awsscs',1,'1.1','mcq',2,$q$Which service continuously scans EC2, ECR images, and Lambda for known vulnerabilities?$q$,$q$["Amazon Inspector","Amazon GuardDuty","AWS WAF","Amazon Macie"]$q$::jsonb,'0'::jsonb,$q$Amazon Inspector performs automated, continuous vulnerability scanning of EC2, container images in ECR, and Lambda, reporting CVEs and reachability. GuardDuty detects threats, WAF filters web traffic, Macie classifies data.$q$),
-- Domain 2: Security Logging & Monitoring
('sc-q-008','awsscs',2,'2.1','mcq',2,$q$Which service records who made which API call, when, and from where, across the account?$q$,$q$["AWS CloudTrail","Amazon CloudWatch","VPC Flow Logs","AWS Config"]$q$::jsonb,'0'::jsonb,$q$CloudTrail logs API activity (identity, action, time, source) for audit and forensics. CloudWatch handles metrics/logs, Flow Logs capture network metadata, Config records resource configuration.$q$),
('sc-q-009','awsscs',2,'2.1','mcq',3,$q$How do you best protect CloudTrail logs from being deleted or altered by an attacker who compromises the account?$q$,$q$["Store them in the same account with default settings","Deliver to a dedicated logging account bucket with log file validation and Object Lock, protected by SCPs","Email logs daily","Disable the trail during incidents"]$q$::jsonb,'1'::jsonb,$q$Isolating logs in a separate logging account with integrity validation, Object Lock/MFA delete, and SCP protection puts them beyond a compromised workload account's reach and makes tampering detectable. Same-account defaults are deletable.$q$),
('sc-q-010','awsscs',2,'2.1','mcq',2,$q$What do VPC Flow Logs capture?$q$,$q$["Full packet payloads","IP traffic metadata: source, destination, ports, bytes, accept/reject","API calls","S3 object contents"]$q$::jsonb,'1'::jsonb,$q$VPC Flow Logs record traffic metadata (not payloads) at the VPC/subnet/ENI level for anomaly detection and troubleshooting, and they feed GuardDuty. Payloads require packet mirroring; API calls are CloudTrail.$q$),
('sc-q-011','awsscs',2,'2.2','mcq',2,$q$How can you receive an alert whenever the root user signs in to the console?$q$,$q$["A Config rule only","A CloudWatch Logs metric filter on CloudTrail for root sign-in, with an alarm and SNS","A Route 53 record","An S3 event"]$q$::jsonb,'1'::jsonb,$q$A metric filter on the CloudTrail log group matching root console sign-in, tied to a CloudWatch alarm and SNS, delivers the alert (a CIS benchmark control). Config/Route 53/S3 events don't detect root logins.$q$),
('sc-q-012','awsscs',2,'2.2','mcq',2,$q$Which service evaluates resources against rules like "no S3 bucket is public" and tracks configuration drift over time?$q$,$q$["AWS Config","CloudTrail","GuardDuty","Macie"]$q$::jsonb,'0'::jsonb,$q$AWS Config records configuration state/history and evaluates resources against Config Rules, supporting remediation and drift detection. CloudTrail logs API calls, GuardDuty detects threats, Macie classifies data.$q$),
('sc-q-013','awsscs',2,'2.1','mcq',2,$q$What does CloudTrail log file validation provide?$q$,$q$["Faster log delivery","Cryptographic digest files to verify logs were not modified or deleted","Encryption in transit only","Automatic log deletion"]$q$::jsonb,'1'::jsonb,$q$Log file validation produces signed digest files so you can prove delivered logs are unaltered - critical for forensic and legal integrity. It's about integrity, not speed, transit encryption, or deletion.$q$),
('sc-q-014','awsscs',2,'2.1','mcq',2,$q$How do you ensure API activity across every account in an Organization is logged and member accounts cannot disable it?$q$,$q$["A per-account trail each admin manages","An organization trail delivering to a central bucket","VPC Flow Logs","A CloudWatch dashboard"]$q$::jsonb,'1'::jsonb,$q$An organization trail centrally logs all member accounts and cannot be disabled or modified by them. Per-account trails can be turned off by account admins; Flow Logs and dashboards aren't API audit trails.$q$),
('sc-q-015','awsscs',2,'2.2','mcq',3,$q$You must centralize logs from 50 accounts for the security team to analyze. What is the BEST design?$q$,$q$["Leave logs in each account","Aggregate CloudTrail/Config/CloudWatch Logs into a dedicated logging account with cross-account permissions and SCP protection","Email logs to the team","Store logs on EC2 instance disks"]$q$::jsonb,'1'::jsonb,$q$A dedicated logging account with aggregated, SCP-protected log storage gives the security team centralized, tamper-resistant visibility. Scattering logs, emailing, or storing on instance disks defeats central analysis and durability.$q$),
-- Domain 3: Infrastructure Security
('sc-q-016','awsscs',3,'3.1','mcq',2,$q$Which provides stateful IPS-style filtering and domain-based rules at the VPC level, beyond security groups and NACLs?$q$,$q$["AWS Network Firewall","A security group","A NACL","Route 53"]$q$::jsonb,'0'::jsonb,$q$AWS Network Firewall offers managed stateful inspection, Suricata IPS rules, and domain filtering at the VPC boundary. Security groups and NACLs are simpler instance/subnet filters; Route 53 is DNS.$q$),
('sc-q-017','awsscs',3,'3.1','matching',2,$q$Match each network control to its scope/behavior.$q$,$q${"left":["Security group","Network ACL","AWS Network Firewall","AWS WAF"],"right":["Stateful, instance-level","Stateless, subnet-level","Stateful IPS/domain filtering, VPC-level","Layer 7 web exploit filtering"]}$q$::jsonb,$q$[0,1,2,3]$q$::jsonb,$q$Security groups are stateful at the instance; NACLs are stateless at the subnet; Network Firewall does stateful IPS/domain filtering at the VPC; WAF filters Layer 7 web exploits. Layered, they provide defense in depth.$q$),
('sc-q-018','awsscs',3,'3.1','mcq',3,$q$Admins need shell access to private EC2 instances with no inbound ports open and full session logging. What should you use?$q$,$q$["An SSH bastion with port 22 open","AWS Systems Manager Session Manager","A public IP on each instance","A NAT Gateway"]$q$::jsonb,'1'::jsonb,$q$Session Manager provides IAM-controlled, fully logged shell access via an outbound connection - no inbound ports or SSH keys. A bastion opens port 22, public IPs expand exposure, and NAT is for outbound internet.$q$),
('sc-q-019','awsscs',3,'3.1','mcq',2,$q$How do you let a private-subnet instance reach S3 without going over the internet?$q$,$q$["Attach a public IP","Use an S3 Gateway VPC endpoint","Open the security group to 0.0.0.0/0","Add an internet gateway route"]$q$::jsonb,'1'::jsonb,$q$A Gateway VPC endpoint keeps S3 traffic on the AWS network, avoiding internet exposure and NAT cost. Public IPs, wide-open security groups, and internet gateway routes all expose traffic to the internet.$q$),
('sc-q-020','awsscs',3,'3.1','mcq',2,$q$What does an endpoint policy on a VPC interface endpoint control?$q$,$q$["The instance size","Which principals and API actions can pass through the endpoint","The billing account","The DNS TTL"]$q$::jsonb,'1'::jsonb,$q$An endpoint policy restricts which principals and actions (e.g., only certain S3 buckets) may traverse the endpoint - tightening least privilege on private connectivity. It has nothing to do with sizing, billing, or DNS.$q$),
('sc-q-021','awsscs',3,'3.2','mcq',2,$q$Which service centrally enforces WAF, Shield Advanced, and security-group policies across all accounts in an Organization?$q$,$q$["AWS Firewall Manager","Amazon Inspector","AWS Config","Amazon Macie"]$q$::jsonb,'0'::jsonb,$q$AWS Firewall Manager centrally configures and enforces WAF rules, Shield Advanced, security groups, and Network Firewall across the org. Inspector scans vulnerabilities, Config tracks state, Macie classifies data.$q$),
('sc-q-022','awsscs',3,'3.2','mcq',2,$q$A public web app faces large volumetric and Layer 7 DDoS attacks and needs cost protection and a response team. Which service?$q$,$q$["AWS Shield Standard","AWS Shield Advanced","A security group","VPC Flow Logs"]$q$::jsonb,'1'::jsonb,$q$Shield Advanced adds Layer 3/4/7 DDoS mitigations, cost protection for attack-driven scaling, WAF integration, and 24/7 DDoS Response Team access. Standard is automatic but basic; security groups and Flow Logs don't stop DDoS.$q$),
('sc-q-023','awsscs',3,'3.1','mcq',2,$q$What is the security purpose of a NAT Gateway?$q$,$q$["Allow inbound internet connections to private instances","Allow outbound internet access from private instances while blocking inbound","Encrypt data at rest","Filter Layer 7 traffic"]$q$::jsonb,'1'::jsonb,$q$A NAT Gateway lets private-subnet instances initiate outbound connections (updates, APIs) without permitting inbound connections from the internet. It doesn't encrypt at rest or do Layer 7 filtering.$q$),
('sc-q-024','awsscs',3,'3.2','mcq',2,$q$Where can AWS WAF be deployed?$q$,$q$["Only on EC2","CloudFront, ALB, API Gateway, and AppSync","Only on S3","Only on RDS"]$q$::jsonb,'1'::jsonb,$q$WAF attaches to CloudFront, Application Load Balancer, API Gateway, and AppSync to filter Layer 7 traffic. It doesn't attach directly to EC2, S3, or RDS.$q$),
-- Domain 4: Identity & Access Management
('sc-q-025','awsscs',4,'4.1','mcq',3,$q$In IAM policy evaluation, which statement is TRUE?$q$,$q$["An explicit Allow overrides an explicit Deny","An explicit Deny always overrides any Allow","Everything is allowed by default","SCPs grant permissions"]$q$::jsonb,'1'::jsonb,$q$Evaluation is default-deny; an explicit Deny anywhere (identity policy, SCP, boundary, resource policy) always wins over Allow. SCPs cap permissions, they never grant them.$q$),
('sc-q-026','awsscs',4,'4.1','mcq',3,$q$What does an IAM permission boundary do?$q$,$q$["Grants administrator access","Sets the maximum permissions an identity can have, without granting them","Encrypts credentials","Logs API calls"]$q$::jsonb,'1'::jsonb,$q$A permission boundary caps the maximum permissions of a user/role - the identity still needs a policy that grants access within that cap. It's ideal for safely delegating role creation. It neither grants, encrypts, nor logs.$q$),
('sc-q-027','awsscs',4,'4.1','mcq',3,$q$An identity policy allows S3FullAccess, but an SCP on the account denies S3 outside us-east-1. What can the identity do?$q$,$q$["Full S3 access everywhere","S3 access only in us-east-1","No S3 access at all","Access is undefined"]$q$::jsonb,'1'::jsonb,$q$Effective permission is the intersection: the grant allows S3, but the SCP's explicit deny outside us-east-1 wins there, leaving S3 access only in us-east-1. Explicit Deny always overrides Allow.$q$),
('sc-q-028','awsscs',4,'4.2','mcq',2,$q$Which service provides centralized single sign-on to many AWS accounts with permission sets and external IdP federation?$q$,$q$["IAM Identity Center","Amazon Cognito","AWS KMS","Amazon Macie"]$q$::jsonb,'0'::jsonb,$q$IAM Identity Center (formerly AWS SSO) centralizes workforce access across accounts with permission sets and federation to Okta/Entra/AD. Cognito targets app end-users; KMS and Macie are unrelated.$q$),
('sc-q-029','awsscs',4,'4.1','mcq',2,$q$How should a workload get temporary, scoped AWS credentials instead of long-term keys?$q$,$q$["Hardcode an IAM user's keys","Assume an IAM role via STS","Use the root user","Share keys across the team"]$q$::jsonb,'1'::jsonb,$q$Assuming a role via STS yields short-lived, scoped, revocable credentials - the secure pattern for workloads, cross-account, and federation. Hardcoded keys, root, and shared keys are all insecure.$q$),
('sc-q-030','awsscs',4,'4.1','mcq',2,$q$Which tool identifies S3 buckets or KMS keys shared with external or public principals?$q$,$q$["IAM Access Analyzer","CloudTrail","AWS Budgets","Route 53"]$q$::jsonb,'0'::jsonb,$q$IAM Access Analyzer flags resources exposed to external/public principals and can generate least-privilege policies from CloudTrail activity. CloudTrail logs calls, Budgets tracks cost, Route 53 is DNS.$q$),
('sc-q-031','awsscs',4,'4.1','mcq',3,$q$Which IAM condition key enforces that an action is only allowed when the caller used MFA?$q$,$q$["aws:SourceIp","aws:MultiFactorAuthPresent","aws:RequestedRegion","aws:username"]$q$::jsonb,'1'::jsonb,$q$aws:MultiFactorAuthPresent true requires the session to be MFA-authenticated. aws:SourceIp restricts by IP, aws:RequestedRegion by region, aws:username by identity - none enforce MFA.$q$),
('sc-q-032','awsscs',4,'4.1','mcq',2,$q$What is a resource-based policy example that enables cross-account access without assuming a role?$q$,$q$["An IAM group policy","An S3 bucket policy granting another account access","A permission boundary","A launch template"]$q$::jsonb,'1'::jsonb,$q$Resource-based policies (S3 bucket policy, KMS key policy, SQS/SNS/Lambda) can grant a principal - including cross-account - direct access. IAM group policies and boundaries are identity-side; launch templates are unrelated.$q$),
-- Domain 5: Data Protection
('sc-q-033','awsscs',5,'5.1','mcq',2,$q$What advantage does a customer-managed KMS key have over an AWS-managed key?$q$,$q$["It is free","Control over rotation policy, key policy, grants, and deletion","It cannot be audited","It never expires"]$q$::jsonb,'1'::jsonb,$q$Customer-managed keys give you control of rotation, key policy, grants, and scheduled deletion; AWS-managed keys are largely automatic with limited configurability. Both are auditable via CloudTrail.$q$),
('sc-q-034','awsscs',5,'5.1','mcq',3,$q$How does KMS avoid exposing the master key while encrypting large objects?$q$,$q$["It sends all data to KMS","Envelope encryption: a data key encrypts the data, and KMS encrypts the data key","It stores keys in plaintext on S3","It uses no keys"]$q$::jsonb,'1'::jsonb,$q$Envelope encryption encrypts data locally with a data key, and KMS only encrypts/decrypts that small data key - the master key never leaves KMS and large data never transits it. Plaintext key storage would be insecure.$q$),
('sc-q-035','awsscs',5,'5.2','mcq',2,$q$Which service uses ML to discover and classify sensitive data such as PII in S3?$q$,$q$["Amazon Macie","Amazon GuardDuty","AWS Config","Amazon Inspector"]$q$::jsonb,'0'::jsonb,$q$Amazon Macie discovers, classifies, and alerts on sensitive data (PII, credentials) in S3. GuardDuty detects threats, Config tracks configuration, Inspector scans for vulnerabilities.$q$),
('sc-q-036','awsscs',5,'5.2','mcq',2,$q$What is the safety net that overrides any policy or ACL granting public access to an S3 bucket?$q$,$q$["S3 Block Public Access","Bucket versioning","Transfer Acceleration","Requester Pays"]$q$::jsonb,'0'::jsonb,$q$S3 Block Public Access settings (account and bucket level) override permissive policies/ACLs, preventing accidental public exposure. Versioning, acceleration, and Requester Pays serve unrelated purposes.$q$),
('sc-q-037','awsscs',5,'5.1','mcq',3,$q$How do you enforce that objects can only be uploaded to a bucket if they are encrypted?$q$,$q$["Enable Transfer Acceleration","A bucket policy denying PutObject when the encryption header is missing/incorrect","Turn on versioning","Add a NAT Gateway"]$q$::jsonb,'1'::jsonb,$q$A bucket policy that denies s3:PutObject lacking the correct encryption header (plus default encryption) enforces encryption at rest on upload. Acceleration, versioning, and NAT don't enforce encryption.$q$),
('sc-q-038','awsscs',5,'5.1','mcq',2,$q$When would you use AWS CloudHSM instead of KMS?$q$,$q$["For cheaper multi-tenant keys","When regulations require single-tenant, FIPS 140-2 Level 3 hardware control of keys","For S3 lifecycle management","For DNS resolution"]$q$::jsonb,'1'::jsonb,$q$CloudHSM provides dedicated single-tenant HSMs with full key control and FIPS 140-2 Level 3 compliance - used when multi-tenant KMS isn't permitted. It's not about cost, lifecycle, or DNS.$q$),
('sc-q-039','awsscs',5,'5.1','mcq',2,$q$What is a KMS grant used for?$q$,$q$["Permanently changing the key policy","Temporarily and revocably delegating specific key operations to a principal or service","Disabling encryption","Storing the key in S3"]$q$::jsonb,'1'::jsonb,$q$Grants delegate scoped, revocable key operations (e.g., to an EBS volume or Lambda) without editing the key policy - least-privilege and temporary. They don't alter policy permanently, disable encryption, or export keys.$q$),
('sc-q-040','awsscs',5,'5.2','mcq',2,$q$How do you enforce encryption in transit for access to AWS resources?$q$,$q$["Rely on the default","Require TLS (ACM certs) and deny non-HTTPS via aws:SecureTransport policy conditions","Use HTTP for speed","Disable VPC endpoints"]$q$::jsonb,'1'::jsonb,$q$Enforcing TLS with ACM certificates and denying requests where aws:SecureTransport is false guarantees encryption in transit; VPC endpoints keep traffic off the internet. Defaults and HTTP don't guarantee it.$q$),
('sc-q-041','awsscs',5,'5.1','mcq',2,$q$What does automatic key rotation do for a customer-managed KMS key?$q$,$q$["Deletes old data","Generates new backing key material yearly while retaining old material to decrypt existing data","Changes the key ID","Disables the key"]$q$::jsonb,'1'::jsonb,$q$Automatic rotation creates new backing material annually, keeps the same key ID, and retains prior material so existing ciphertext still decrypts - transparent to applications. It doesn't delete data or change the key ID.$q$),
('sc-q-042','awsscs',5,'5.1','mcq',3,$q$Which correctly distinguishes a KMS key policy from a grant?$q$,$q$["They are identical","The key policy is the primary resource policy; grants are temporary programmatic delegations","Grants are permanent; key policies are temporary","Only grants control access"]$q$::jsonb,'1'::jsonb,$q$The key policy is the primary, durable resource policy governing key use/management; grants are temporary, revocable, programmatic delegations of specific operations. Both together determine access.$q$),
-- Domain 6: Management & Security Governance
('sc-q-043','awsscs',6,'6.1','mcq',2,$q$Which mechanism prevents any account in an Organization from disabling CloudTrail?$q$,$q$["An IAM policy","A Service Control Policy (SCP) denying cloudtrail:StopLogging","A security group","A bucket policy"]$q$::jsonb,'1'::jsonb,$q$An SCP denying CloudTrail stop/delete actions caps every member account regardless of local admin rights - a preventive org-wide guardrail. IAM policies, security groups, and bucket policies don't enforce org-wide.$q$),
('sc-q-044','awsscs',6,'6.1','mcq',2,$q$Which service sets up a governed multi-account landing zone with guardrails, a log archive account, and an audit account?$q$,$q$["AWS Control Tower","AWS Config","Amazon Inspector","AWS Shield"]$q$::jsonb,'0'::jsonb,$q$Control Tower provisions and governs a secure multi-account landing zone with SCP+Config guardrails and dedicated log-archive and audit accounts. Config, Inspector, and Shield are point services, not landing-zone orchestration.$q$),
('sc-q-045','awsscs',6,'6.1','mcq',3,$q$How do you restrict accounts to only operate in approved AWS regions?$q$,$q$["A NACL","An SCP denying actions when aws:RequestedRegion is not in an allowed list","A security group","A Route 53 policy"]$q$::jsonb,'1'::jsonb,$q$An SCP condition on aws:RequestedRegion denies actions outside approved regions across the org. NACLs and security groups are network controls; Route 53 is DNS - none enforce regional governance.$q$),
('sc-q-046','awsscs',6,'6.2','mcq',2,$q$What does an AWS Config conformance pack provide?$q$,$q$["A single firewall rule","A packaged set of Config rules and remediations mapped to a compliance framework, deployable across accounts","A KMS key","A load balancer"]$q$::jsonb,'1'::jsonb,$q$Conformance packs bundle Config rules and remediation actions aligned to frameworks (e.g., PCI, CIS) for consistent multi-account governance. They aren't firewall rules, keys, or load balancers.$q$),
('sc-q-047','awsscs',6,'6.2','mcq',2,$q$Which service checks the account against best practices like exposed access keys, open security groups, and MFA on root?$q$,$q$["AWS Trusted Advisor","Amazon Kinesis","AWS Batch","Amazon SQS"]$q$::jsonb,'0'::jsonb,$q$Trusted Advisor evaluates the account against best practices (security, cost, performance) and flags issues like public snapshots and open ports. Kinesis, Batch, and SQS are unrelated data/compute services.$q$),
('sc-q-048','awsscs',6,'6.1','mcq',2,$q$What is a key security benefit of a multi-account strategy?$q$,$q$["Lower total number of resources","Blast-radius isolation and separation of duties across dedicated accounts","Elimination of IAM","Free data transfer"]$q$::jsonb,'1'::jsonb,$q$Separating workloads and functions (logging, audit, security) into distinct accounts limits blast radius, enforces separation of duties, and clarifies guardrails. It doesn't eliminate IAM or make transfer free.$q$),
('sc-q-049','awsscs',6,'6.2','mcq',2,$q$How does Security Hub support ongoing governance?$q$,$q$["By blocking all traffic","By continuously running compliance-standard checks (CIS, PCI, FSBP) and aggregating findings org-wide","By encrypting volumes","By managing DNS"]$q$::jsonb,'1'::jsonb,$q$Security Hub continuously evaluates against security standards and aggregates prioritized findings with remediation guidance across the org - a governance and posture-management hub. It doesn't block traffic, encrypt, or do DNS.$q$),
('sc-q-050','awsscs',6,'6.1','mcq',3,$q$A company wants preventive guardrails that even account administrators cannot override. Which control type fits?$q$,$q$["Detective Config rules","Preventive SCPs","Reactive Lambda functions","CloudWatch dashboards"]$q$::jsonb,'1'::jsonb,$q$SCPs are preventive guardrails capping what accounts can do regardless of local admin rights. Config rules are detective (they flag after the fact), Lambda is reactive, and dashboards are visibility only.$q$);
